def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    if not alive_opponents:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water >= 1:
            base = DAILY_SALARY * 0.75
        return max(0, min(budget, base))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= DAILY_SALARY * 4:
            rich_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid', 0))

    high_supply = supply >= 22
    low_supply = supply <= 17

    if hp <= 1:
        bid = DAILY_SALARY * 0.98
    elif hp <= 2 or no_water >= 2:
        bid = DAILY_SALARY * 0.9
    elif no_water >= 1:
        bid = DAILY_SALARY * 0.78
    else:
        if high_supply:
            bid = DAILY_SALARY * 0.42
        elif low_supply:
            bid = DAILY_SALARY * 0.62
        else:
            bid = DAILY_SALARY * 0.52

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
        if hp <= 2 or no_water >= 1:
            bid = max(bid, highest_prev + 2)
        else:
            if high_supply:
                bid = max(bid, avg_prev * 0.92)
            elif low_supply:
                bid = max(bid, highest_prev + 1.5)
            else:
                bid = max(bid, avg_prev + 0.5)

    if desperate_count >= 2:
        bid += 4
    elif desperate_count == 1:
        bid += 2

    if rich_count >= 2 and not (hp <= 2 or no_water >= 1):
        bid += 2

    if day >= 8:
        bid += 3
    if day == 10:
        bid += 4

    reserve = 0
    if hp > 2 and no_water == 0 and day <= 4:
        reserve = DAILY_SALARY * 0.25
    elif day <= 7:
        reserve = DAILY_SALARY * 0.1

    affordable = max(0, budget - reserve)
    if hp <= 2 or no_water >= 1:
        affordable = budget

    bid = min(bid, affordable)
    bid = min(bid, budget)
    bid = max(0, bid)
    return bid

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 150
    WATER_REQ = 13
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    supply = day_context['supply']

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not alive_opponents:
        return float(min(my_status['budget'], 10.0))

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if supply < (len(alive_opponents) + 1) * WATER_REQ:
            return float(min(my_status['budget'], max_prev + 5.0))
        return float(min(my_status['budget'], max(20.0, max_prev * 0.8)))

    return float(min(my_status['budget'], 50.0))
